package psx;

import javax.microedition.lcdui.Graphics;

/**
 * Built-in 5x7 bitmap font (ASCII + Cyrillic). Generated by
 * tools/mkfont.py - do not edit by hand.
 *
 * Every label of the MIDlet is drawn with this font, so text is
 * visible even on handsets whose system font has no Cyrillic glyphs
 * or ignores Graphics.setFont().
 */
public final class TinyFont {

    public static final int WIDTH = 6;
    public static final int HEIGHT = 8;
    private static final int GLYPH_W = 5;
    private static final int ROWS = 7;

    /** Printable charset, one char per glyph, in table order. */
    private static final String CHARS = "\040\041\042\043\044\045\046\047\050\051\052\053\054\055\056\057\060\061\062\063\064\065\066\067\070\071\072\073\074\075\076\077\100\101\102\103\104\105\106\107\110\111\112\113\114\115\116\117\120\121\122\123\124\125\126\127\130\131\132\133\134\135\136\137\140\141\142\143\144\145\146\147\150\151\152\153\154\155\156\157\160\161\162\163\164\165\166\167\170\171\172\173\174\175\176\u0401\u0451\u0410\u0411\u0412\u0413\u0414\u0415\u0416\u0417\u0418\u0419\u041a\u041b\u041c\u041d\u041e\u041f\u0420\u0421\u0422\u0423\u0424\u0425\u0426\u0427\u0428\u0429\u042a\u042b\u042c\u042d\u042e\u042f\u0430\u0431\u0432\u0433\u0434\u0435\u0436\u0437\u0438\u0439\u043a\u043b\u043c\u043d\u043e\u043f\u0440\u0441\u0442\u0443\u0444\u0445\u0446\u0447\u0448\u0449\u044a\u044b\u044c\u044d\u044e\u044f\u00ab\u00bb\u2014\u2026\u2116\u00b0\u2192\u2190\u25b6";

    /** 14 hex digits per glyph: 7 rows, 2 digits each, 5 low bits = pixels. */
    private static final String DATA = ""
        + ""
        + ""
        + "1715171f010018080e0b090f0012121a1e161a0010101c16121e001c020e02061c0016151d1d1516001c14140c141400000a1e141e0a000014160a16140000001f1f1f1f00000000001e1e1e1c1c1d1f1f17081c1414141c08000002031f0302000008181f180800101c1e1f1c10";

    private TinyFont() { }

    /** Fallback index: '?' */
    private static final int FALLBACK = 31;

    private static int glyphIndex(char c) {
        if (c >= 32 && c < 127) return c - 32;
        if (c == '\u0401') return 95;
        if (c == '\u0451') return 96;
        if (c >= '\u0410' && c <= '\u044f') return 97 + (c - '\u0410');
        int extra = EXTRA.indexOf(c);
        return extra < 0 ? FALLBACK : 161 + extra;
    }

    /** Extra glyphs outside the ASCII / Cyrillic ranges. */
    private static final String EXTRA = "«»—…№°→←▶";

    private static int hex(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        return c - 'a' + 10;
    }

    public static int stringWidth(String s) {
        return s == null ? 0 : s.length() * WIDTH;
    }

    public static int charWidth(char c) { return WIDTH; }

    /** Human readable form: replaces glyphs this font cannot draw. */
    private static char mapChar(char c) { return c; }

    public static void draw(Graphics g, String s, int x, int y, int anchor) {
        draw(g, s, x, y, anchor, false, 1);
    }

    public static void draw(Graphics g, String s, int x, int y, int anchor,
                            boolean bold) {
        draw(g, s, x, y, anchor, bold, 1);
    }

    public static void draw(Graphics g, String s, int x, int y, int anchor,
                            boolean bold, int scale) {
        if (s == null || s.length() == 0) return;
        if (scale < 1) scale = 1;
        int w = stringWidth(s) * scale;
        int h = HEIGHT * scale;
        int ax = anchor & 0x0f;
        int ay = anchor & 0xf0;
        if (ax == Graphics.HCENTER) x -= w / 2;
        else if (ax == Graphics.RIGHT) x -= w;
        if (ay == Graphics.BOTTOM) y -= h;
        else if (ay == Graphics.BASELINE) y -= 6 * scale;
        for (int i = 0; i < s.length(); i++) {
            int gi = glyphIndex(s.charAt(i));
            int gx = x + i * WIDTH * scale;
            for (int row = 0; row < ROWS; row++) {
                int p = (gi * ROWS + row) * 2;
                int bits = (hex(DATA.charAt(p)) << 4) | hex(DATA.charAt(p + 1));
                if (bits == 0) continue;
                int col = 0;
                while (col < GLYPH_W) {
                    if ((bits & (1 << (GLYPH_W - 1 - col))) == 0) { col++; continue; }
                    int run = 1;
                    while (col + run < GLYPH_W
                            && (bits & (1 << (GLYPH_W - 1 - col - run))) != 0) run++;
                    g.fillRect(gx + col * scale, y + row * scale, run * scale, scale);
                    /* Bold is expressed with colour, not a second pass:
                       at 5x7 a doubled glyph turns Cyrillic into mush. */
                    col += run;
                }
            }
        }
    }

    /** Draws a string clipped to maxW pixels, ending with "..." when needed. */
    public static String ellipsize(String s, int maxW) {
        if (s == null) return "";
        int maxChars = maxW / WIDTH;
        if (maxChars < 4) maxChars = 4;
        if (s.length() <= maxChars) return s;
        return s.substring(0, maxChars - 3) + "...";
    }
}
